from griffe.extensions import Extension
from griffe.docstrings.dataclasses import Docstring
import griffe

class CheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_function_loaded(self, function):
        """Append ' [checked]' to the docstring of every loaded function."""
        if function.docstring:
            function.docstring.value += " [checked]"
        else:
            function.docstring = Docstring(" [checked]", 0, 0)

# Load the package with the extension enabled
extension = CheckedExtension()
mypkg = griffe.load("mypkg", extensions=[extension])

# Display results to verify
for name, obj in mypkg.members.items():
    if hasattr(obj, 'docstring') and obj.docstring:
